head.script:
scwin.trigger1_onclick = function(e) {
    var id = "addTAB" + i;
    var tabOptions = {
        label: "addTab",
        addTabIndex: 0
    };
    var contentsOptions = {
        frameMode: "iframe",
        src: "http://www.daum.net"
    };
    tabControl1.addTab(id, tabOptions, contentsOptions);
    i++;
};
scwin.__closeIsATag = function() {
    var nodeName = WebSquare.wUnit.getDomById($p.id + "tabControl1_tab_tabs5_close").nodeName;
    return (nodeName == "A") && (typeof(WebSquare.wUnit.getDomById($p.id + "tabControl1_tab_tabs5_close").href) != "undefined");
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 실행 후 개발자모드(F12) > Tabcontrol의 닫기버튼을 Elements로 검사하고 오른쪽 개발자모드의 한단계 아래를 클릭(역삼각형모양)한다.
    //1. After executing the sample file, check the close button of Developer mode (F12)> Tabcontrol with Elements and click under one step of the right developer mode (inverted triangle).
    // verify step 1. a태그로 되어있고 href속성도 추가되어 보여진다.(이전에는 div태그로 되어있었음)
    //1. It is tagged with a and has the href attribute added (formerly div tag).
    WebSquare.wUnit.addCommand("assert", "scwin.__closeIsATag()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.i = 0;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 06-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
